module benchmark/solution
import std/net (httpRequest)
import std/io (println)

export func main() -> () ! {IO, Net} {
  let headers = [
    {name: "X-Test-Header", value: "value123"},
    {name: "Content-Type", value: "application/json"}
  ];
  let body = "{\"message\":\"Hello from AILANG\",\"count\":42}";
  match httpRequest("POST", "http://127.0.0.1:7655", headers, body) {
    Ok(response) => println(show(response.status)),
    Err(_) => println("0")
  }
}

